    raise exception 'Level % not found for course % -- refusing to guess', 1, v_course_id;
  end if;

  -- The new modules must sit INSIDE this level, not at the end of the
  -- course. getOrderedLessons() builds the learner's lesson sequence from
  -- modules.order_number alone and ignores level, so a module appended at
  -- the course's max order would put beginner content after the final
  -- level's material. Insert straight after this level's last module and
  -- shift everything below it down instead.
  select coalesce(max(order_number), 0) into v_module_offset
    from public.modules where level_id = v_level;

  -- Two-phase shift: (course_id, order_number) is unique, and a single
  -- "+ N" update can trip that constraint mid-statement, so park the rows
  -- out of range first and bring them back afterwards.
  update public.modules set order_number = order_number + 1000
   where course_id = v_course_id and order_number > v_module_offset;

  insert into public.modules (course_id, level_id, title, description, order_number) values
    (v_course_id, v_level, 'What Every App Is Actually Made Of', 'Level 1 asked what no-code is and compared the tools, then Level 2 went straight to building in specific apps. The concepts underneath — that a screen is made of components, and that an app needs somewhere to keep its data — are the same in every no-code tool, and were never taught. FlutterFlow is used here as the worked example because its own channel teaches these properly; the ideas transfer to Glide, Adalo, Bubble or anything else.', v_module_offset + 1)
  returning id into v_m1;

  insert into public.lessons (module_id, title, description, youtube_url, order_number, learning_objectives, notes, practice_activity, knowledge_check) values
    (v_m1, 'Screens Are Made of Components', 'The building-block idea behind every app screen: containers, text, images and buttons arranged inside each other. From FlutterFlow''s own channel.', 'https://www.youtube.com/watch?v=2TGhJEUA0uY', 1,
      array['Describe a screen as a tree of nested components rather than a picture', 'Name the handful of component types that make up most screens', 'Recognise the same idea in a different no-code tool'],
      'The mental shift that makes no-code click: a screen is not a drawing, it is a structure. A card is a container holding an image, some text and a button. A list is one design repeated for each row of data. Once you see screens as nested boxes, every tool''s editor stops being mysterious, because they are all editing the same structure with different names for it.

FlutterFlow calls them widgets. Glide calls them components. Adalo calls them components too. Bubble calls them elements. The vocabulary differs; the idea does not. That is why this lesson sits in Level 1, before the course picks a tool.

ADDITION BEYOND THE VIDEO — why this matters for getting unstuck. Most beginner frustration in no-code is a layout that will not do what you want, and almost all of it comes from not knowing which container a thing is sitting inside. When something will not move, will not centre, or will not resize, the answer is nearly always in the structure tree, not in the settings panel you are staring at. Learn to read that tree first and you will solve your own problems instead of searching for a tutorial that matches your exact screen.

A note on this course''s tools: the Glide lessons in Level 2 use Glide''s older product, which the vendor has since moved on from. The concepts in this module are the durable part; specific button positions in any tool will drift, and that is normal.',
      'Open any app on your phone and pick one screen. On paper, draw it as nested boxes: what contains what. Mark every repeated row as one design plus data. Then open any no-code tool''s free tier and rebuild just that structure — no colours, no polish, only the boxes in the right arrangement. Getting the tree right is the skill; decoration is the easy part.',
      '[{"question":"What is the underlying idea behind every app screen?","options":["A picture that the tool converts into code","A tree of components nested inside each other — a card is a container holding an image, text and a button","A single template chosen from a gallery","A spreadsheet with formatting applied"],"correct_index":1},{"question":"Your element will not centre or resize the way you want. Where is the answer usually found?","options":["In the settings panel for that element","In the tool''s colour and theme settings","In the structure tree — which container the element is sitting inside","In the app''s export settings"],"correct_index":2}]'::jsonb),
    (v_m1, 'Where the App Keeps Its Data', 'Connecting an app to a database and showing real, saved information — built as a to-do app, the smallest example that needs everything. From FlutterFlow''s own channel.', 'https://www.youtube.com/watch?v=TFsDJAhvAKQ', 2,
      array['Explain why an app needs a database separate from its screens', 'Set up a collection and connect a screen to it', 'Tell the difference between data that is saved and data that only looks saved'],
      'This is the half of app-building that beginners skip and then cannot understand why nothing works. Screens display; the database remembers. If a to-do list loses its items when you close the app, the items were never in a database — they were only ever on screen.

A to-do app is the standard teaching example for a reason: it is the smallest thing that needs all the pieces. Something to store items, a screen that lists them, a way to add one, a way to mark it done. Every business app you will ever be asked for — a stock list, a client register, an attendance sheet, a delivery tracker — is the same shape with different words.

FlutterFlow uses Firebase and Firestore here, which is Google''s database service. Other tools bundle their own: Glide sits on a sheet, Adalo has its own collections, Bubble has a built-in database. The concepts you need are identical — collections of records, each with fields — and only the setup screens differ.

ADDITION BEYOND THE VIDEO — two things to check before you build for a paying client. First, cost: free tiers are generous for learning and can become billable when an app has real users, and a Firebase bill arrives in dollars. Read the pricing page before you promise anything. Second, where the data lives: a client storing customer names and phone numbers has obligations under Kenya''s Data Protection Act. Know what you are storing and why, do not collect what you do not need, and be able to tell the client where it is kept.',
      'Build the smallest possible data-backed app: one collection with two fields, one screen that lists the records, and one button that adds a record. Then close the app completely and reopen it. If your records are still there, you have understood this lesson. If they are gone, you built a screen, not an app — find where the save step was missed.',
      '[{"question":"Your to-do list loses its items when the app is closed. What does that tell you?","options":["The app needs more memory","The items were never saved to a database — they only ever existed on screen","The screen layout is wrong","The database is too small"],"correct_index":1},{"question":"Why is a to-do app the standard teaching example?","options":["It is the most commonly requested business app","It requires no database","It is the smallest thing that needs all the pieces — storage, a list, adding and updating — and every business app is that same shape","It can be built without any screens"],"correct_index":2}]'::jsonb)
  on conflict (module_id, order_number) do nothing;

  -- Bring the shifted modules back, now sitting after the 1 new one(s).
  update public.modules set order_number = order_number - 1000 + 1
